/// <summary>
/// DebuC 20.09.23
/// </summary>
/// <param name = "firma">NDXCompanys</param>
/// <param name = "alliance">KCS_BOSAllianceID</param>
/// <param name = "child">KCS_BOSAllianceID</param>
/// <returns>str</returns>
static str conSubAlliance2QueryValue(NDXCompanys     firma,
                                 KCS_BOSAllianceID   alliance,
                                 KCS_BOSAllianceID   child)
{
    container   conChilds;
    int         i, l_conLen;
    str         qValue = '';
    ;
    conChilds = NDXAllianceTree::getChilds(firma, alliance, child);
    l_conLen = conlen(conChilds);
    for (i = 1; i <= l_conLen; i++)
    {
        qValue += conpeek(conChilds, i);
        if (i < l_conLen)
        {
            qValue += ', ';
        }
    }
    return qValue;
}

/// <summary>
/// DebuC 20.09.23
/// </summary>
/// <param name = "firma">NDXCompanys</param>
/// <param name = "alliance">KCS_BOSAllianceID</param>
/// <param name = "child">KCS_BOSAllianceID</param>
/// <param name = "lWithInfo">boolean</param>
/// <param name = "lInitStructure">boolean</param>
/// <returns>container</returns>
static container getChilds(NDXCompanys         firma,
                        KCS_BOSAllianceID   alliance,
                        KCS_BOSAllianceID   child,
                        boolean             lWithInfo       = false,
                        boolean             lInitStructure  = false)
{
    NDXAllianceTree     nDXAllianceTree;
    NDXAllianceTree     nDXAllianceTree2;

    container           conChilds = connull();
    str                 strChilds;
    int                 i, l_conLen;

    // rekursive Methode, zur Ermittlung der Unterstrukturen
    void getValues(KCS_BOSAllianceID   lAlliance)
    {
        NDXAllianceTree    lnDXAllianceTree2;
        ;
        while select        lnDXAllianceTree2
        where           lNDXAllianceTree2.Company     == firma     &&
                        lnDXAllianceTree2.Alliance  == alliance  &&
                        lnDXAllianceTree2.Parent    == lAlliance
        {
            conChilds   += lnDXAllianceTree2.Child;
            getValues(lnDXAllianceTree2.Child);
        }

    }
    ;
    // Initialisierung der Verbandsstruktur
    if (lInitStructure)
    {
        if (lWithInfo)
        {
            info(strfmt("@NDX:NDXStartInitAllianceStructure", NDXHelperCommon::seconds2Str(DateTimeUtil::getTimeNow(DateTimeUtil::getUserPreferredTimeZone()))));         // [%1] Start: Verbandsstruktur initialisieren
        }
        NDXVerbandSE::getAllianceParentChild();
        if (lWithInfo)
        {
            info(strfmt("@NDX:NDXEndInitAllianceStructure", NDXHelperCommon::seconds2Str(DateTimeUtil::getTimeNow(DateTimeUtil::getUserPreferredTimeZone())) ));         // [%1] Ende : Verbandsstruktur initialisieren
        }
    }

    // child in der Strutkur vorhanden?
    {
        select firstonly nDXAllianceTree
        where   nDXAllianceTree.Company      == firma    &&
                nDXAllianceTree.Child      == child;
        if (nDXAllianceTree)
        {
            conChilds   += child;
        }
    }

    // hat child weitere childs?
    if (lWithInfo)
    {
        info(strfmt("@NDX:NDXStartDetermineChilds",                                                     // [%1] Start: Ermittlung der Childs für Unter-Struktur [%2-%3]
                NDXHelperCommon::seconds2Str(DateTimeUtil::getTimeNow(DateTimeUtil::getUserPreferredTimeZone())),  alliance, child));
    }
    {
        while select        nDXAllianceTree2
        where           nDXAllianceTree2.Company     == firma        &&
                        nDXAllianceTree2.Alliance  == alliance     &&
                        nDXAllianceTree2.Parent    == child        &&
                        nDXAllianceTree2.Level
        {
            conChilds   += nDXAllianceTree2.Child;
            getValues(nDXAllianceTree2.Child);
        }
    }

    if (lWithInfo)
    {
        l_conLen = conlen(conChilds);
        for (i = 1; i <= l_conLen; i++)
        {
            strChilds += conpeek(conChilds,i);
            if (i < l_conLen)
            {
                strChilds += ', ';
            }
        }
        info(strfmt("@NDX:NDXEndDetermineChilds",                               // [%1] Ende : Ermittlung der Childs für Unter-Struktur [%2-%3] childs [%4]
        NDXHelperCommon::seconds2Str(DateTimeUtil::getTimeNow(DateTimeUtil::getUserPreferredTimeZone())),  alliance, child, strChilds));
    }
    return conChilds;
}

/// <summary>
/// DebuC 20.09.23
/// static void insert() in AX2009
/// </summary>
/// <param name = "firma">NDXCompanys</param>
/// <param name = "alliance">KCS_BOSAllianceID</param>
/// <param name = "parent">KCS_BOSAllianceID</param>
/// <param name = "child">KCS_BOSAllianceID</param>
/// <param name = "party">RefRecId</param>
/// <param name = "level">NDXLevel</param>
static void insertRecords(NDXCompanys      firma,
                KCS_BOSAllianceID   alliance,
                KCS_BOSAllianceID   parent,
                KCS_BOSAllianceID   child,
                RefRecId            party,
                NDXLevel            level)
{
    NDXAllianceTree        nDXAllianceTree;
    ;
    try
    {
        nDXAllianceTree.initValue();
        nDXAllianceTree.Company    = firma;
        nDXAllianceTree.Alliance   = alliance;
        nDXAllianceTree.Parent     = parent;
        nDXAllianceTree.Child      = child;
        nDXAllianceTree.Party      = party;
        nDXAllianceTree.Level      = level;
        nDXAllianceTree.insert();
    }
    catch
    {
        info(strfmt("@NDX:NDXCouldntCreateAllianceTree", alliance, parent, child, level ));  // Record in NDX_AllianceTree konnte nicht angelegt werden: Alliance[%1] Parent[%2] Child[%3] Level[%4]
    }
}

/// <summary>
/// DebuC 20.09.23
/// </summary>
/// <param name = "firma">NDXCompanys</param>
/// <param name = "child">KCS_BOSAllianceID</param>
/// <param name = "l_forUpdate">boolean</param>
/// <returns>NDXAllianceTree</returns>
static NDXAllianceTree findChild(NDXCompanys         firma,
                              KCS_BOSAllianceID   child,
                              boolean             l_forUpdate = false)
{
    NDXAllianceTree    nDXAllianceTree;
    ;
    nDXAllianceTree.selectForUpdate(l_forUpdate);

    if (child)
    {
        select      nDXAllianceTree
            where   nDXAllianceTree.Company  == firma &&
                    nDXAllianceTree.Child  == child;
    }
    return nDXAllianceTree;
}

/// <summary>
/// DebuC 20.09.23
/// </summary>
/// <param name = "child">KCS_BOSAllianceID</param>
/// <returns>NDXLevel</returns>
static NDXLevel getLevel(KCS_BOSAllianceID   child)
{
    return (select  NDXAllianceTree
        where   NDXAllianceTree.Child ==  child).Level;
}
